def compute_order_amount(history_demand, history_inventory, history_lost, holding_cost, lost_sales_cost):
    smoothing_factor = 0.1  # Optimized
    cost_normalization = 0.5063412492746919  # Optimized
    volatility_scale = 1.702270791020659  # Optimized
    min_coverage = 1.1  # Optimized

    if len(history_demand) == 0:
        demand_estimate = 20  # Optimized
    else:
        demand_estimate = history_demand[-1] * smoothing_factor + (1 - smoothing_factor) * (sum(history_demand)/len(history_demand) if len(history_demand) > 0 else 0)

    cost_ratio = lost_sales_cost / (holding_cost + lost_sales_cost + 1e-6)
    normalized_cost = (cost_ratio - 0.5) * cost_normalization + 0.5

    if len(history_demand) >= 2:
        demand_volatility = 1.0  # Optimized
    else:
        demand_volatility = 0.5  # OPT_PARAM: {'initial': 0.5, 'min': 0.1, 'max': 1.0, 'type': 'float'}

    safety_stock = demand_estimate * volatility_scale * demand_volatility * normalized_cost
    target_inventory = max(demand_estimate * min_coverage, demand_estimate + safety_stock)
    order_amount = max(0, target_inventory - history_inventory[-1])

    return order_amount
